package com.utec.tropelcare.controller; import com.utec.tropelcare.dto.*; import com.utec.tropelcare.service.TropelService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/tropels") public class TropelController{private final TropelService s;public TropelController(TropelService s){this.s=s;}@PostMapping public ResponseEntity<TropelDto> create(@Valid @RequestBody TropelRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping public PageResponse<TropelDto> search(@RequestParam(required=false) String species,@RequestParam(required=false) String vitalState,@RequestParam(required=false) Long sectorId,@RequestParam(required=false) Long guardianId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return s.search(species,vitalState,sectorId,guardianId,page,size);}@GetMapping("/{id}") public TropelDto get(@PathVariable Long id){return s.get(id);}@GetMapping("/{id}/diary") public DiaryDto diary(@PathVariable Long id){return s.diary(id);}}
